ax[0,1].set_xticks([0,1,2],['Frozen latent control','Joint adapters','Full-weight short'],rotation=8);ax[0,1].set_ylabel('GT-context free skeleton J2J ×100')
for i,g in enumerate(generations[-2:]):
    for j,m in enumerate(['surface','rig']):
        key=m+'_iou';v=[r[key]*100 for r in g['runs']];x=i*2+j;ax[1,0].scatter(x+np.linspace(-.07,.07,3),v,color=colors[i]);ax[1,0].errorbar(x,np.mean(v),yerr=np.std(v,ddof=1),color=colors[i],capsize=4)
ax[1,0].set_xticks([0,1,2,3],['MSE surface','MSE rig','Balanced surface','Balanced rig'],rotation=12);ax[1,0].set_ylabel('Single-image occupied64³ IoU (%)')
