ax[1,1].set_xticks([0,1],['Standard MSE','Balanced-rig diagnostic']);ax[1,1].set_ylabel('Single-image cases per30');ax[1,1].set_ylim(0,32);ax[1,1].legend(fontsize=8,loc='upper right');fig.savefig(out/'comparison.png',dpi=170);plt.close(fig)
fmt=lambda m,scale=100:f"{m['mean']*scale:.{6 if scale==1 else 3}f} ± {m['std']*scale:.{6 if scale==1 else 3}f}"
lines=['# Round3: pretrained TRELLIS and full-weight joint audit','',summary['scope'],'',summary['claim'],'','## GT-conditioned reconstruction and support controls','',f"Official pretrained encoder+mesh: {base['nonempty']}/10 nonempty, mesh CD×100={base['chamfer_all_empty_penalty']*100:.3f}. GT-support zero-channel shell (no learned decoder): {shell['nonempty']}/10 nonempty, CD×100={shell['chamfer_all_empty_penalty']*100:.3f}. GT positions explain a substantial part of low reconstruction distance; neither result is image generation.",'',f"Official occupancy VAE GT-mask reconstruction IoU: surface={occ['surface']:.6f}, rig={occ['rig']:.6f}. Decoder inputs are GT-encoded latents, not generated structure.",'','| Three-seed GT-context task | Mesh CD×100 | Free J2J×100 | GT-bone element L1×100 | Cap hits /30 |','|---|---:|---:|---:|---:|',f"| Frozen latent decoder control | fixed official mesh above | {fmt(summary['frozen_decoder_control']['j2j'])} | {fmt(summary['frozen_decoder_control']['skin_l1'])} | {summary['frozen_decoder_control']['cap_hits']}/30 |"]
